  @override
  String get unMotEstAfficheChaque =>
      'Εμφανίζεται μια λέξη. Κάθε παίκτης πρέπει να υποβάλει κρυφά ένα συνώνυμο. Όλες οι απαντήσεις αποκαλύπτονται και στη συνέχεια οι παίκτες ψηφίζουν για να «αποκλείσουν» τη λιγότερο σχετική πρόταση. Ο αποκλεισμένος παίκτης χάνει τον γύρο.';

  @override
  String get plusieursCategoriesSontSelectionnees3 =>
      'Επιλέγονται διάφορες κατηγορίες (τουλάχιστον 3). Εμφανίζεται μια κατηγορία (π.χ. μάρκα αυτοκινήτου). Κάθε παίκτης με τη σειρά του πρέπει να γράψει μια έγκυρη λέξη (π.χ. Volvo, Citroën) πριν από το τέλος του χρονομέτρου του. Εάν ένας παίκτης δεν απαντήσει εγκαίρως, κερδίζει 1 πόντο. Ο παίκτης με τους λιγότερους πόντους κερδίζει.';

  @override
